args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import fs from 'node:fs'
import ts from 'typescript'
import React from 'react'
import { renderToStaticMarkup } from 'react-dom/server'

const source = fs.readFileSync('app/UserStats.tsx', 'utf8')
const { outputText } = ts.transpileModule(source, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.React },
})
const componentModule = { exports: {} }
new Function('exports', 'React', outputText)(componentModule.exports, React)
const UserStats = componentModule.exports.default
for (const [name, statuses] of [
  ['mixed', [true, false, true]],
  ['empty', []],
  ['all active', [true, true]],
  ['all inactive', [false, false]],
]) {
  const users = statuses.map((isActive, id) => ({ id, name: "'`User ${id}`, isActive }))
  console.log(`${name}: ${renderToStaticMarkup(React.createElement(UserStats, { users }))}`)
}
NODE'

